solution:
function IsPalindrome(s: string) -> bool {
  let cleaned: string[] = [];
  let chars = s.chars();
  let n = chars.length();
  let i = 0;
  while (i < n) {
    let c = chars[i];
    if (c.is_alphanumeric()) {
      cleaned.push(c.to_lower_case());
    }
    i += 1;
  }
  let lo = 0;
  let hi = cleaned.length() - 1;
  while (lo < hi) {
    if (cleaned[lo] != cleaned[hi]) {
      return false;
    }
    lo += 1;
    hi -= 1;
  }
  return true;
}
